select 
from ygb_worker_job_post
where del_flag = '0'
  and status = '0'

  and (
    title like concat('%', #{keyword}, '%')
    or enterprise_name like concat('%', #{keyword}, '%')
    or job_type like concat('%', #{keyword}, '%')
  )


  and job_type = #{jobType}


  and ifnull(salary_max, salary_min) >= #{salaryMin}


  and ifnull(salary_min, salary_max) <= #{salaryMax}

order by job_id desc

